def main():
    target = os.getcwd()
    if os.path.exists(os.path.join(target, "KeyFlow")):
        print("ERROR: ./KeyFlow already exists here. Move it or run in an empty folder.")
        sys.exit(1)
    raw = base64.b64decode("".join(DATA.split()))
    with zipfile.ZipFile(io.BytesIO(raw)) as zf:
        zf.extractall(target)
        count = len(zf.namelist())
    for rel in ("KeyFlow/gradlew", "KeyFlow/tools/ci_gradle.sh", "KeyFlow/tools/ci_instrumented.sh",
                "KeyFlow/tools/ci_prepare_metadata.sh", "KeyFlow/tools/generate_reproducibility_metadata.sh",
                "KeyFlow/tools/validate_unix.sh"):
        p = os.path.join(target, rel)
        if os.path.isfile(p):
            os.chmod(p, os.stat(p).st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
    print("Restored %d files into %s" % (count, os.path.join(target, "KeyFlow")))
    print("Next: cd KeyFlow && git init -b main && git add -A && git commit -m 'KeyFlow rc21' "
          "&& git remote add origin <repo-url> && git push -u origin main")

if __name__ == "__main__":
    main()
